// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;

    // the test contract itself is the creator of c (setUp deploys it),
    // so give it a receive() so the mutant's transfer to creator can succeed
    receive() external payable {}

    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 amount, address payer) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(payer != address(c));
        amount = bound(amount, 1, 1 ether * 1000);

        // fund the contract with the fuzzed deposit
        vm.deal(payer, amount);
        vm.prank(payer);
        c.deposit{value: amount}();

        // creator is address(this); migrate to a recipient that REFUSES ETH
        Reverter to = new Reverter();
        bool ok = false;
        vm.prank(address(this));
        try c.migrateTo(address(to)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: when the designated recipient refuses the transfer,
        // migrateTo must fail rather than divert the funds elsewhere.
        // Reference: transfer to the reverter reverts -> ok is false for EVERY input.
        // Mutant: transfers the whole balance to the creator, which succeeds -> ok is true.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
